// Regression fixture for #59 — subpath-imports laundering past the ESM resolve hook.
//
// None of these specifiers NAMES a mediated builtin, so a resolve hook that classifies on the
// specifier string alone lets them through to the raw builtin. They all resolve to one, which
// is why capwall must classify on the URL Node resolves to. Kept deliberately inert per
// AGENTS.md § 8: it reads only its own data.txt and spawns `node -e ""`, which does nothing.
import { fileURLToPath } from "node:url";

const DATA = fileURLToPath(new URL("./data.txt", import.meta.url));

/** Returns one `"<route>:<OUTCOME>"` line per laundering route, for the app to print. */
export async function launder() {
  const out = [];

  for (const [route, spec] of [
    ["bare-fs", "#bare-fs"],
    ["cond-fs", "#cond-fs"],
    ["pat-fs", "#pat/fs"],
  ]) {
    try {
      const fs = await import(spec);
      out.push(`${route}:RAW:${fs.readFileSync(DATA, "utf8").trim()}`);
    } catch (err) {
      out.push(`${route}:${err && err.name === "CapabilityError" ? `BLOCKED:${err.pkg}` : `ERR:${err && err.code}`}`);
    }
  }

  try {
    const cp = await import("#bare-cp");
    cp.execSync(`${process.execPath} -e ""`);
    out.push("bare-cp:RAW");
  } catch (err) {
    out.push(`bare-cp:${err && err.name === "CapabilityError" ? `BLOCKED:${err.pkg}` : `ERR:${err && err.code}`}`);
  }

  return out;
}
